    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY where RECORD_SOURCE = 'OPUS_CP_PARTNERS' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
