-- STEP 4 (force the change) -- fill <BK> from STEP 3, run this UPDATE in UTILS. STEP 5: dbt run --select this sat. STEP 6: set phase='AFTER' and re-run STEP 2.
-- OPUS_AZBJ_PARTNER_EXTN (BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN
   set "ECS_STATUS" = coalesce(to_varchar("ECS_STATUS"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "PART_ID" = '<PART_ID>';

