    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_VEHICLE_PRIOR_INSURANCE where RECORD_SOURCE = 'OPUS_BJAZ_SPP_MEMBER_DTLS' order by hkey limit 100
