 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via stg_partner__bjaz_spp_member_dtls (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS)
select 'SAT_PARTY_VEHICLE_PRIOR_INSURANCE' as satellite, 'OPUS_BJAZ_SPP_MEMBER_DTLS' as record_source,
