select 'SAT_COMMON_ADDRESS' as satellite, 'stitch_common_address (5 tables)' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("BILLING_LOC"::varchar), '')))) AS VARCHAR))), '')) as hkey, (nullif(trim("BILLING_LOC"::varchar), '')) as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN
 where (nullif(trim("BILLING_LOC"::varchar), '')) is not null and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("BILLING_LOC"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
