       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE_MASTER' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE_MASTER
 where (nullif(trim("PINCODE"::varchar), '')) is not null and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("PINCODE"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s_bk)
