-- via OPUS_BJAZ_M_KYC_DRIVING_LICENCE (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_M_KYC_DRIVING_LICENCE)
select 'SAT_COMMON_ADDRESS' as satellite, 'stitch_kyc_common_address (6 tables)' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || ((case when nullif(upper(trim(to_varchar((nullif(trim("ADDRESS"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("ZIP_CODE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("ADDRESS"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("ZIP_CODE"::varchar), ''))))), ''), '') end)) AS VARCHAR))), '')) as hkey, case when nullif(upper(trim(to_varchar((nullif(trim("ADDRESS"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("ZIP_CODE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("ADDRESS"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("ZIP_CODE"::varchar), ''))))), ''), '') end as business_key, (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_M_KYC_DRIVING_LICENCE' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_M_KYC_DRIVING_LICENCE
 where case when nullif(upper(trim(to_varchar((nullif(trim("ADDRESS"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("ZIP_CODE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("ADDRESS"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("ZIP_CODE"::varchar), ''))))), ''), '') end is not null and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || ((case when nullif(upper(trim(to_varchar((nullif(trim("ADDRESS"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("ZIP_CODE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("ADDRESS"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("ZIP_CODE"::varchar), ''))))), ''), '') end)) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via OPUS_BJAZ_M_KYC_GSTN (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_M_KYC_GSTN)
select 'SAT_COMMON_ADDRESS' as satellite, 'stitch_kyc_common_address (6 tables)' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || ((case when nullif(upper(trim(to_varchar((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), ''), '') end)) AS VARCHAR))), '')) as hkey, case when nullif(upper(trim(to_varchar((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), ''), '') end as business_key, (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_M_KYC_GSTN' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_M_KYC_GSTN
 where case when nullif(upper(trim(to_varchar((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), ''), '') end is not null and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || ((case when nullif(upper(trim(to_varchar((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), ''), '') end)) AS VARCHAR))), '')) in (select hkey from s_bk)
