     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_COMMON_ADDRESS'
),
a as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'AFTER'  and satellite = 'SAT_COMMON_ADDRESS'
),
k as (
    select b.satellite, b.record_source, b.hkey, b.cdk,
           not equal_null(b.raw_hash, a.raw_hash) as raw_changed,
           a.sat_rows - b.sat_rows as new_rows
      from b join a
        on a.satellite = b.satellite and a.record_source = b.record_source
       and a.hkey = b.hkey and equal_null(a.cdk, b.cdk)
)
select 'OPUS' as project, satellite, record_source,
       count(*) as changed_keys,
       count_if(new_rows >= 1) as changed_with_new_row,
       count_if(new_rows < 1)  as changed_without_new_row,
       iff(changed_keys = 0, 'NOT TESTED (no source change in sample)',
           iff(changed_without_new_row = 0, 'PASS', 'FAIL')) as status
  from k
 where raw_changed
 group by satellite, record_source
 order by iff(status = 'FAIL', 0, 1), record_source;



----------------------------------------------------------------------------------------
-- 9. OPUS — [M1 | stitch_incremental] SAT_COMMON_ADMIN_GEOGRAPHY   [Design finding]
-- HASHDIFF of stitch_shared__common_admin_geography_common_geo (2 tables)
-- (stg2_shared__common_admin_geography_common_geo) also hashes REGIONCODE, REGIONNAME,
-- SUBZONECODE, ZONECODE, which this satellite does not store (a shared stage feeding
-- several satellites). A change in only those columns gives a new HASHDIFF and so a NEW
-- ROW WITH AN UNCHANGED PAYLOAD here -- breaks DM-H2; see DM-H2 (a)
-- unchanged_payload_reinserts. The HASHDIFF cannot be recomputed from the satellite row.
-- standard satellite, automate_dv.sat; PK LOCATION_HKEY; 1 RECORD_SOURCE group(s):
-- stitch_shared__common_admin_geography_common_geo (2 tables) [1 col(s)].
----------------------------------------------------------------------------------------
-- STEP 1 (static, run anytime) -- HASHDIFF integrity. PASS here = the change-detection fingerprint is sound. SQL query (a)
-- DM-H1 (a) OPUS SAT_COMMON_ADMIN_GEOGRAPHY: HASHDIFF not recomputable -- see note

-- STEP 2 (BEFORE) -- set $DM_H_RUN (with your <M#>) and $DM_H_PHASE='BEFORE', then run this CDC capture. Re-run it again in STEP 6 after setting phase to AFTER.
insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct LOCATION_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADMIN_GEOGRAPHY where regexp_like(RECORD_SOURCE, '^(OPUS_BJAZ_PINCODE|OPUS_BJAZ_PINCODE_MASTER)(, (OPUS_BJAZ_PINCODE|OPUS_BJAZ_PINCODE_MASTER))*$') order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_COMMON_ADMIN_GEOGRAPHY' and record_source = 'stitch_shared__common_admin_geography_common_geo (2 tables)'
),
g1_t0 as (  -- stitch source OPUS_BJAZ_PINCODE
    select distinct (nullif(trim("PINCODE"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("PINCODE"::varchar), '')))), '') as pincode,
           nullif(trim(to_varchar((nullif(trim("ZONE1"::varchar), '')))), '') as regioncode,
           nullif(trim(to_varchar((nullif(trim("STATE"::varchar), '')))), '') as regionname,
           nullif(trim(to_varchar((nullif(trim("ZONE2"::varchar), '')))), '') as subzonecode,
           nullif(trim(to_varchar((nullif(trim("ZONE"::varchar), '')))), '') as zonecode,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE
     where (nullif(trim("PINCODE"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("PINCODE"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t1 as (  -- stitch source OPUS_BJAZ_PINCODE_MASTER
    select distinct (nullif(trim("PINCODE"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("PINCODE"::varchar), '')))), '') as pincode,
           nullif(trim(to_varchar((nullif(trim("ZONE1"::varchar), '')))), '') as regioncode,
           nullif(trim(to_varchar((nullif(trim("STATE"::varchar), '')))), '') as regionname,
           nullif(trim(to_varchar((nullif(trim("ZONE2"::varchar), '')))), '') as subzonecode,
           nullif(trim(to_varchar((nullif(trim("ZONE_PIN"::varchar), '')))), '') as zonecode,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE_MASTER
     where (nullif(trim("PINCODE"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("PINCODE"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
k1 as (
    select parent_bk from g1_t0
    union
    select parent_bk from g1_t1
),
st1 as (  -- stitch_shared__common_admin_geography_common_geo recomputed from RAW (same coalesce / priority as the stitch macro)
    select ak.parent_bk,
           coalesce(g1_t0.pincode, g1_t1.pincode) as pincode,
           coalesce(g1_t0.regioncode, g1_t1.regioncode) as regioncode,
           coalesce(g1_t0.regionname, g1_t1.regionname) as regionname,
           coalesce(g1_t0.subzonecode, g1_t1.subzonecode) as subzonecode,
           coalesce(g1_t0.zonecode, g1_t1.zonecode) as zonecode,
           array_to_string(array_construct_compact(
               case when g1_t0.parent_bk is not null then 'OPUS_BJAZ_PINCODE' end,
               case when g1_t1.parent_bk is not null then 'OPUS_BJAZ_PINCODE_MASTER' end
           ), ', ') as record_source,
           greatest_ignore_nulls(g1_t0.inc_job_updated_at, g1_t1.inc_job_updated_at) as inc_job_updated_at
      from k1 ak
      left join g1_t0 on g1_t0.parent_bk = ak.parent_bk
      left join g1_t1 on g1_t1.parent_bk = ak.parent_bk
    qualify row_number() over (partition by ak.parent_bk order by g1_t0.pincode nulls last, g1_t0.regioncode nulls last, g1_t0.regionname nulls last, g1_t0.subzonecode nulls last, g1_t0.zonecode nulls last, g1_t1.pincode nulls last, g1_t1.regioncode nulls last, g1_t1.regionname nulls last, g1_t1.subzonecode nulls last, g1_t1.zonecode nulls last) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stitch_shared__common_admin_geography_common_geo
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || st.parent_bk AS VARCHAR))), '')) as hkey,
               st.inc_job_updated_at as ldts,
               to_varchar(st.pincode) as PINCODE
          from st1 st
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select LOCATION_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADMIN_GEOGRAPHY
     where regexp_like(RECORD_SOURCE, '^(OPUS_BJAZ_PINCODE|OPUS_BJAZ_PINCODE_MASTER)(, (OPUS_BJAZ_PINCODE|OPUS_BJAZ_PINCODE_MASTER))*$') and LOCATION_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(IFNULL(NULLIF(UPPER(TRIM(CAST(e.PINCODE AS VARCHAR))), ''), '^^'))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'OPUS', 'SAT_COMMON_ADMIN_GEOGRAPHY', 'stitch_shared__common_admin_geography_common_geo (2 tables)',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;

-- STEP 3 (pick a key) -- map a sampled BEFORE hkey to its RAW business key. Copy one business_key value to use in STEP 4.
with s_bk as (  -- sampled BEFORE hkeys for this satellite
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_COMMON_ADMIN_GEOGRAPHY'
)
-- via OPUS_BJAZ_PINCODE (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE)
select 'SAT_COMMON_ADMIN_GEOGRAPHY' as satellite, 'stitch_shared__common_admin_geography_common_geo (2 tables)' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("PINCODE"::varchar), '')))) AS VARCHAR))), '')) as hkey, (nullif(trim("PINCODE"::varchar), '')) as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE
 where (nullif(trim("PINCODE"::varchar), '')) is not null and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("PINCODE"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via OPUS_BJAZ_PINCODE_MASTER (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE_MASTER)
select 'SAT_COMMON_ADMIN_GEOGRAPHY' as satellite, 'stitch_shared__common_admin_geography_common_geo (2 tables)' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("PINCODE"::varchar), '')))) AS VARCHAR))), '')) as hkey, (nullif(trim("PINCODE"::varchar), '')) as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE_MASTER' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE_MASTER
 where (nullif(trim("PINCODE"::varchar), '')) is not null and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("PINCODE"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s_bk)
limit 20;

-- STEP 4 (force the change) -- fill <BK> from STEP 3, run this UPDATE in UTILS. STEP 5: dbt run --select this sat. STEP 6: set phase='AFTER' and re-run STEP 2.
-- OPUS_BJAZ_PINCODE source (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE): change ONE sampled key
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE
   set "PINCODE" = coalesce(to_varchar("PINCODE"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "PINCODE" = '<PINCODE>';

-- OPUS_BJAZ_PINCODE_MASTER source (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE_MASTER): change ONE sampled key
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE_MASTER
   set "PINCODE" = coalesce(to_varchar("PINCODE"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "PINCODE" = '<PINCODE>';

-- STEP 7 (result for THIS sat) -- after AFTER capture, run this. PASS = every changed key got >= 1 new row; NOT TESTED = no change reached the sample.
with b as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_COMMON_ADMIN_GEOGRAPHY'
),
a as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'AFTER'  and satellite = 'SAT_COMMON_ADMIN_GEOGRAPHY'
),
k as (
    select b.satellite, b.record_source, b.hkey, b.cdk,
           not equal_null(b.raw_hash, a.raw_hash) as raw_changed,
           a.sat_rows - b.sat_rows as new_rows
      from b join a
        on a.satellite = b.satellite and a.record_source = b.record_source
       and a.hkey = b.hkey and equal_null(a.cdk, b.cdk)
)
select 'OPUS' as project, satellite, record_source,
       count(*) as changed_keys,
       count_if(new_rows >= 1) as changed_with_new_row,
       count_if(new_rows < 1)  as changed_without_new_row,
       iff(changed_keys = 0, 'NOT TESTED (no source change in sample)',
           iff(changed_without_new_row = 0, 'PASS', 'FAIL')) as status
  from k
 where raw_changed
 group by satellite, record_source
 order by iff(status = 'FAIL', 0, 1), record_source;



----------------------------------------------------------------------------------------
-- 10. OPUS — [M1 | stitch_incremental] SAT_PARTY_IDENTITY   [Implemented]
-- HASHDIFF column HASHDIFF. Recomputed exactly as automate_dv 0.11.5 / sat_multi_source
-- computes it, from the payload stored on the same row. A match proves every payload
-- change changes the HASHDIFF, which is what drives a new row. standard satellite,
-- sat_multi_source; PK PARTY_HKEY; 9 RECORD_SOURCE group(s): stitch_party_identity (19
-- tables) [17 col(s)], OPUS_BJAZ_T_CKYC_PERSONAL_DTLS [9 col(s)],
-- OPUS_BJAZ_T_CKYC_REL_PERSION_DTLS [4 col(s)], OPUS_BJAZ_T_CKYC_SEARCH [3 col(s)],
-- OPUS_BJAZ_T_EKYC [3 col(s)], OPUS_BJAZ_T_KYC_AUTH [3 col(s)], OPUS_BJAZ_T_KYC_DETAILS
-- [3 col(s)], OPUS_BJAZ_T_KYC_INCOMING [4 col(s)], OPUS_BJAZ_T_KYC_OCR [5 col(s)].
----------------------------------------------------------------------------------------
-- STEP 1 (static, run anytime) -- HASHDIFF integrity. PASS here = the change-detection fingerprint is sound. SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'OPUS' as project, 'SAT_PARTY_IDENTITY' as satellite, '9 RECORD_SOURCEs sharing one HASHDIFF column list' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF is null) as null_hashdiff,
       count_if(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(AGE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DATEOFBIRTH AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DATEOFDEATH AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(FIRSTNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(GENDERCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(LASTNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MIDDLENAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NAMESUFFIX AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NATIONALITY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYDISPLAYNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYFULLNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYLEGALNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYSHORTNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYSTATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYTYPECODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PLACEOFBIRTH AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SALUTATION AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(AGE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DATEOFBIRTH AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DATEOFDEATH AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(FIRSTNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(GENDERCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(LASTNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MIDDLENAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NAMESUFFIX AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NATIONALITY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYDISPLAYNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYFULLNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYLEGALNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYSHORTNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYSTATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYTYPECODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PLACEOFBIRTH AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SALUTATION AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY
 where (regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_PARTNER_EXTN|OPUS_BA_HCP_DT_MEM|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_CTNGY_FF_DTLS_EXTN|OPUS_BJAZ_CTNGY_GC_MEM_DATA|OPUS_BJAZ_CTNGY_PA_MEM_DTLS|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HLT_ENSURE_MEM_DTLS|OPUS_BJAZ_HM_HOSPITAL_MASTER|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_INTERMEDIARY|OPUS_BJAZ_PA_DETL_EXTN|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_BJAZ_STARPKG_FF_DTLS|OPUS_CP_PARTNERS|OPUS_OCP_INTERESTED_PARTIES)(, (OPUS_AZBJ_PARTNER_EXTN|OPUS_BA_HCP_DT_MEM|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_CTNGY_FF_DTLS_EXTN|OPUS_BJAZ_CTNGY_GC_MEM_DATA|OPUS_BJAZ_CTNGY_PA_MEM_DTLS|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HLT_ENSURE_MEM_DTLS|OPUS_BJAZ_HM_HOSPITAL_MASTER|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_INTERMEDIARY|OPUS_BJAZ_PA_DETL_EXTN|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_BJAZ_STARPKG_FF_DTLS|OPUS_CP_PARTNERS|OPUS_OCP_INTERESTED_PARTIES))*$')) or (RECORD_SOURCE = 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS') or (RECORD_SOURCE = 'OPUS_BJAZ_T_CKYC_REL_PERSION_DTLS') or (RECORD_SOURCE = 'OPUS_BJAZ_T_CKYC_SEARCH') or (RECORD_SOURCE = 'OPUS_BJAZ_T_EKYC') or (RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_AUTH') or (RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_DETAILS') or (RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_INCOMING') or (RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_OCR');

-- STEP 2 (BEFORE) -- set $DM_H_RUN (with your <M#>) and $DM_H_PHASE='BEFORE', then run this CDC capture. Re-run it again in STEP 6 after setting phase to AFTER.
insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY where regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_PARTNER_EXTN|OPUS_BA_HCP_DT_MEM|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_CTNGY_FF_DTLS_EXTN|OPUS_BJAZ_CTNGY_GC_MEM_DATA|OPUS_BJAZ_CTNGY_PA_MEM_DTLS|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HLT_ENSURE_MEM_DTLS|OPUS_BJAZ_HM_HOSPITAL_MASTER|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_INTERMEDIARY|OPUS_BJAZ_PA_DETL_EXTN|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_BJAZ_STARPKG_FF_DTLS|OPUS_CP_PARTNERS|OPUS_OCP_INTERESTED_PARTIES)(, (OPUS_AZBJ_PARTNER_EXTN|OPUS_BA_HCP_DT_MEM|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_CTNGY_FF_DTLS_EXTN|OPUS_BJAZ_CTNGY_GC_MEM_DATA|OPUS_BJAZ_CTNGY_PA_MEM_DTLS|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HLT_ENSURE_MEM_DTLS|OPUS_BJAZ_HM_HOSPITAL_MASTER|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_INTERMEDIARY|OPUS_BJAZ_PA_DETL_EXTN|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_BJAZ_STARPKG_FF_DTLS|OPUS_CP_PARTNERS|OPUS_OCP_INTERESTED_PARTIES))*$') order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_PARTY_IDENTITY' and record_source = 'stitch_party_identity (19 tables)'
),
g1_t0 as (  -- stitch source OPUS_AZBJ_PARTNER_EXTN
