      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY
     where RECORD_SOURCE = 'OPUS_BJAZ_T_CKYC_REL_PERSION_DTLS' and PARTY_HKEY in (select hkey from s3)
     group by 1, 2
),
x3 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.FIRSTNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.LASTNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.MIDDLENAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.SALUTATION AS VARCHAR))), ''), '^^')))) as raw_hash
      from e3 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'OPUS', 'SAT_PARTY_IDENTITY', 'OPUS_BJAZ_T_CKYC_REL_PERSION_DTLS',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n3 n full outer join x3 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s4 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY where RECORD_SOURCE = 'OPUS_BJAZ_T_CKYC_SEARCH' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_PARTY_IDENTITY' and record_source = 'OPUS_BJAZ_T_CKYC_SEARCH'
),
e4 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_partner__bjaz_t_ckyc_search
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(upper(trim(coalesce((nullif(trim("CATEGORY"::varchar), '')),''))) || ':' || upper(trim(coalesce((nullif(trim("INPUT"::varchar), '')),''))), ':')) AS VARCHAR))), '')) as hkey,
               (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as ldts,
               to_varchar((nullif(trim("DOB"::varchar), ''))) as DATEOFBIRTH,
               to_varchar((nullif(trim("GENDER"::varchar), ''))) as GENDERCODE,
               to_varchar((nullif(trim("FULL_NAME"::varchar), ''))) as PARTYFULLNAME
          from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_SEARCH
      )
     where hkey in (select hkey from s4) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n4 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY
     where RECORD_SOURCE = 'OPUS_BJAZ_T_CKYC_SEARCH' and PARTY_HKEY in (select hkey from s4)
     group by 1, 2
),
x4 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.DATEOFBIRTH AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.GENDERCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PARTYFULLNAME AS VARCHAR))), ''), '^^')))) as raw_hash
      from e4 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'OPUS', 'SAT_PARTY_IDENTITY', 'OPUS_BJAZ_T_CKYC_SEARCH',
