    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY where RECORD_SOURCE = 'OPUS_BJAZ_T_EKYC' order by hkey limit 100
