-- STEP 3 (pick a key) -- map a sampled BEFORE hkey to its RAW business key. Copy one business_key value to use in STEP 4.
with s_bk as (  -- sampled BEFORE hkeys for this satellite
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_PARTY_IDENTITY'
)
-- via OPUS_AZBJ_PARTNER_EXTN (BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN)
select 'SAT_PARTY_IDENTITY' as satellite, 'stitch_party_identity (19 tables)' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PART_ID"::varchar), '')))) AS VARCHAR))), '')) as hkey, (nullif(trim("PART_ID"::varchar), '')) as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN
 where (nullif(trim("PART_ID"::varchar), '')) is not null and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PART_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
