 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(upper(trim(coalesce((nullif(trim("FIELD_TYPE"::varchar), '')),''))) || ':' || upper(trim(coalesce((nullif(trim("FIELD_VALUE"::varchar), '')),''))), ':')) AS VARCHAR))), '')) in (select hkey from s_bk)
limit 20;

