       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(upper(trim(coalesce((nullif(trim("FIELD_TYPE"::varchar), '')),''))) || ':' || upper(trim(coalesce((nullif(trim("FIELD_VALUE"::varchar), '')),''))), ':')) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("FIELD_TYPE"), '^^') || '|' || coalesce(to_varchar("FIELD_VALUE"), '^^') as business_key, (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as inc_job_updated_at,
