-- STEP 7 (result for THIS sat) -- after AFTER capture, run this. PASS = every changed key got >= 1 new row; NOT TESTED = no change reached the sample.
with b as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS'
),
a as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'AFTER'  and satellite = 'SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS'
),
k as (
    select b.satellite, b.record_source, b.hkey, b.cdk,
           not equal_null(b.raw_hash, a.raw_hash) as raw_changed,
           a.sat_rows - b.sat_rows as new_rows
      from b join a
        on a.satellite = b.satellite and a.record_source = b.record_source
       and a.hkey = b.hkey and equal_null(a.cdk, b.cdk)
)
select 'OPUS' as project, satellite, record_source,
       count(*) as changed_keys,
       count_if(new_rows >= 1) as changed_with_new_row,
       count_if(new_rows < 1)  as changed_without_new_row,
       iff(changed_keys = 0, 'NOT TESTED (no source change in sample)',
           iff(changed_without_new_row = 0, 'PASS', 'FAIL')) as status
  from k
 where raw_changed
 group by satellite, record_source
 order by iff(status = 'FAIL', 0, 1), record_source;



----------------------------------------------------------------------------------------
-- 12. OPUS — [M1 | stitch_incremental] SAT_POLICY_HEADER   [Implemented]
-- HASHDIFF column HASHDIFF. Recomputed exactly as automate_dv 0.11.5 / sat_multi_source
-- computes it, from the payload stored on the same row. A match proves every payload
-- change changes the HASHDIFF, which is what drives a new row. standard satellite,
-- automate_dv.sat; PK POLICY_HKEY; 1 RECORD_SOURCE group(s): stitch_policy_header (10
-- tables) [5 col(s)].
----------------------------------------------------------------------------------------
-- STEP 1 (static, run anytime) -- HASHDIFF integrity. PASS here = the change-detection fingerprint is sound. SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'OPUS' as project, 'SAT_POLICY_HEADER' as satellite, 'stitch_policy_header (10 tables)' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF is null) as null_hashdiff,
       count_if(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(MASTERPOLICYREFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POLICYREFERENCENUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POLICYTERM AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(RISKEXPIRYDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(RISKINCEPTIONDATE AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(MASTERPOLICYREFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POLICYREFERENCENUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POLICYTERM AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(RISKEXPIRYDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(RISKINCEPTIONDATE AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(POLICY_HKEY, 'HEX'), null)) within group (order by POLICY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_HEADER
 where (regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_PARTNER_EXTN|OPUS_BJAZ_CTNGY_GC_MEM_DATA|OPUS_BJAZ_CTNGY_PA_MEM_DTLS|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_PA_DETL_EXTN|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS)(, (OPUS_AZBJ_PARTNER_EXTN|OPUS_BJAZ_CTNGY_GC_MEM_DATA|OPUS_BJAZ_CTNGY_PA_MEM_DTLS|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_PA_DETL_EXTN|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS))*$'));

-- STEP 2 (BEFORE) -- set $DM_H_RUN (with your <M#>) and $DM_H_PHASE='BEFORE', then run this CDC capture. Re-run it again in STEP 6 after setting phase to AFTER.
insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct POLICY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_HEADER where regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_PARTNER_EXTN|OPUS_BJAZ_CTNGY_GC_MEM_DATA|OPUS_BJAZ_CTNGY_PA_MEM_DTLS|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_PA_DETL_EXTN|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS)(, (OPUS_AZBJ_PARTNER_EXTN|OPUS_BJAZ_CTNGY_GC_MEM_DATA|OPUS_BJAZ_CTNGY_PA_MEM_DTLS|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_PA_DETL_EXTN|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS))*$') order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_POLICY_HEADER' and record_source = 'stitch_policy_header (10 tables)'
),
g1_t0 as (  -- stitch source OPUS_AZBJ_PARTNER_EXTN
    select distinct (nullif(trim("EXISTING_POLICY_PID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("POLICY_REF"::varchar), '')))), '') as policyreferencenumber,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN
     where (nullif(trim("EXISTING_POLICY_PID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("EXISTING_POLICY_PID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t0b as (  -- stitch source OPUS_BJAZ_CTNGY_GC_MEM_DATA
    select distinct (nullif(trim("POLICY_REF"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("MASTER_POLICY_REF"::varchar), '')))), '') as masterpolicyreference,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_GC_MEM_DATA
     where (nullif(trim("POLICY_REF"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("POLICY_REF"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t1 as (  -- stitch source OPUS_BJAZ_CTNGY_PA_MEM_DTLS
    select distinct (nullif(trim("CONTRACT_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar(("MEMBER_RISK_EXPIRY_DATE"::timestamp_ntz))), '') as riskexpirydate,
           nullif(trim(to_varchar(("MEMBER_RISK_INCEPTION_DATE"::timestamp_ntz))), '') as riskinceptiondate,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_PA_MEM_DTLS
     where (nullif(trim("CONTRACT_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t2 as (  -- stitch source OPUS_BJAZ_EC_MEM_DTLS_EXTN
    select distinct (nullif(trim("CONTRACT_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("POLICY_REF"::varchar), '')))), '') as policyreferencenumber,
           nullif(trim(to_varchar(("EXPIRY_DATE"::timestamp_ntz))), '') as riskexpirydate,
           nullif(trim(to_varchar(("EFFETIVE_DATE"::timestamp_ntz))), '') as riskinceptiondate,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN
     where (nullif(trim("CONTRACT_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t3 as (  -- stitch source OPUS_BJAZ_HCF_MEMBER_DTLS
    select distinct (nullif(trim("CONTRACT_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar(("TO_DATE"::timestamp_ntz))), '') as riskexpirydate,
           nullif(trim(to_varchar(("FROM_DATE"::timestamp_ntz))), '') as riskinceptiondate,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS
     where (nullif(trim("CONTRACT_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t4 as (  -- stitch source OPUS_BJAZ_HC_PART_EXTN
    select distinct (nullif(trim("CONTRACT_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar(("INCEPTION_DATE"::timestamp_ntz))), '') as riskinceptiondate,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HC_PART_EXTN
     where (nullif(trim("CONTRACT_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t5 as (  -- stitch source OPUS_BJAZ_HM_MEMBER_DTLS
    select distinct (nullif(trim("CONTRACT_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("POLICY_REF"::varchar), '')))), '') as policyreferencenumber,
           nullif(trim(to_varchar(("TERM_END_DATE"::timestamp_ntz))), '') as riskexpirydate,
           nullif(trim(to_varchar(("TERM_START_DATE"::timestamp_ntz))), '') as riskinceptiondate,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS
     where (nullif(trim("CONTRACT_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t6 as (  -- stitch source OPUS_BJAZ_PA_DETL_EXTN
    select distinct (nullif(trim("CONTRACT_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar(("INCEPTION_DATE"::timestamp_ntz))), '') as riskinceptiondate,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PA_DETL_EXTN
     where (nullif(trim("CONTRACT_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t7 as (  -- stitch source OPUS_BJAZ_SH_MEM_DTLS_EXTN
    select distinct (nullif(trim("CONTRACT_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("POLICY_REF"::varchar), '')))), '') as policyreferencenumber,
           nullif(trim(to_varchar((nullif(trim("PERIOD_OF_INSURANCE"::varchar), '')))), '') as policyterm,
           nullif(trim(to_varchar(("EXPIRY_DATE"::timestamp_ntz))), '') as riskexpirydate,
           nullif(trim(to_varchar(("EFFETIVE_DATE"::timestamp_ntz))), '') as riskinceptiondate,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN
     where (nullif(trim("CONTRACT_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t8 as (  -- stitch source OPUS_BJAZ_SPP_MEMBER_DTLS
    select distinct (nullif(trim("CONTRACT_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar(("TO_DATE"::timestamp_ntz))), '') as riskexpirydate,
           nullif(trim(to_varchar(("FROM_DATE"::timestamp_ntz))), '') as riskinceptiondate,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS
     where (nullif(trim("CONTRACT_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
k1 as (
    select parent_bk from g1_t0
    union
    select parent_bk from g1_t0b
    union
    select parent_bk from g1_t1
    union
    select parent_bk from g1_t2
    union
    select parent_bk from g1_t3
    union
    select parent_bk from g1_t4
    union
    select parent_bk from g1_t5
    union
    select parent_bk from g1_t6
    union
    select parent_bk from g1_t7
    union
    select parent_bk from g1_t8
),
st1 as (  -- stitch_policy_header recomputed from RAW (same coalesce / priority as the stitch macro)
    select ak.parent_bk,
           g1_t0b.masterpolicyreference as masterpolicyreference,
           coalesce(g1_t0.policyreferencenumber, g1_t2.policyreferencenumber, g1_t5.policyreferencenumber, g1_t7.policyreferencenumber) as policyreferencenumber,
           g1_t7.policyterm as policyterm,
           coalesce(g1_t1.riskexpirydate, g1_t2.riskexpirydate, g1_t3.riskexpirydate, g1_t5.riskexpirydate, g1_t7.riskexpirydate, g1_t8.riskexpirydate) as riskexpirydate,
           coalesce(g1_t1.riskinceptiondate, g1_t2.riskinceptiondate, g1_t3.riskinceptiondate, g1_t4.riskinceptiondate, g1_t5.riskinceptiondate, g1_t6.riskinceptiondate, g1_t7.riskinceptiondate, g1_t8.riskinceptiondate) as riskinceptiondate,
           array_to_string(array_construct_compact(
               case when g1_t0.parent_bk is not null then 'OPUS_AZBJ_PARTNER_EXTN' end,
               case when g1_t0b.parent_bk is not null then 'OPUS_BJAZ_CTNGY_GC_MEM_DATA' end,
               case when g1_t1.parent_bk is not null then 'OPUS_BJAZ_CTNGY_PA_MEM_DTLS' end,
               case when g1_t2.parent_bk is not null then 'OPUS_BJAZ_EC_MEM_DTLS_EXTN' end,
               case when g1_t3.parent_bk is not null then 'OPUS_BJAZ_HCF_MEMBER_DTLS' end,
               case when g1_t4.parent_bk is not null then 'OPUS_BJAZ_HC_PART_EXTN' end,
               case when g1_t5.parent_bk is not null then 'OPUS_BJAZ_HM_MEMBER_DTLS' end,
               case when g1_t6.parent_bk is not null then 'OPUS_BJAZ_PA_DETL_EXTN' end,
               case when g1_t7.parent_bk is not null then 'OPUS_BJAZ_SH_MEM_DTLS_EXTN' end,
               case when g1_t8.parent_bk is not null then 'OPUS_BJAZ_SPP_MEMBER_DTLS' end
           ), ', ') as record_source,
           greatest_ignore_nulls(g1_t0.inc_job_updated_at, g1_t0b.inc_job_updated_at, g1_t1.inc_job_updated_at, g1_t2.inc_job_updated_at, g1_t3.inc_job_updated_at, g1_t4.inc_job_updated_at, g1_t5.inc_job_updated_at, g1_t6.inc_job_updated_at, g1_t7.inc_job_updated_at, g1_t8.inc_job_updated_at) as inc_job_updated_at
      from k1 ak
      left join g1_t0 on g1_t0.parent_bk = ak.parent_bk
      left join g1_t0b on g1_t0b.parent_bk = ak.parent_bk
      left join g1_t1 on g1_t1.parent_bk = ak.parent_bk
      left join g1_t2 on g1_t2.parent_bk = ak.parent_bk
      left join g1_t3 on g1_t3.parent_bk = ak.parent_bk
      left join g1_t4 on g1_t4.parent_bk = ak.parent_bk
      left join g1_t5 on g1_t5.parent_bk = ak.parent_bk
      left join g1_t6 on g1_t6.parent_bk = ak.parent_bk
      left join g1_t7 on g1_t7.parent_bk = ak.parent_bk
      left join g1_t8 on g1_t8.parent_bk = ak.parent_bk
    qualify row_number() over (partition by ak.parent_bk order by g1_t0.policyreferencenumber nulls last, g1_t0b.masterpolicyreference nulls last, g1_t1.riskexpirydate nulls last, g1_t1.riskinceptiondate nulls last, g1_t2.policyreferencenumber nulls last, g1_t2.riskexpirydate nulls last, g1_t2.riskinceptiondate nulls last, g1_t3.riskexpirydate nulls last, g1_t3.riskinceptiondate nulls last, g1_t4.riskinceptiondate nulls last, g1_t5.policyreferencenumber nulls last, g1_t5.riskexpirydate nulls last, g1_t5.riskinceptiondate nulls last, g1_t6.riskinceptiondate nulls last, g1_t7.policyreferencenumber nulls last, g1_t7.policyterm nulls last, g1_t7.riskexpirydate nulls last, g1_t7.riskinceptiondate nulls last, g1_t8.riskexpirydate nulls last, g1_t8.riskinceptiondate nulls last) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stitch_policy_header
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || st.parent_bk AS VARCHAR))), '')) as hkey,
               st.inc_job_updated_at as ldts,
               to_varchar(st.masterpolicyreference) as MASTERPOLICYREFERENCE,
               to_varchar(st.policyreferencenumber) as POLICYREFERENCENUMBER,
               to_varchar(st.policyterm) as POLICYTERM,
               to_varchar(st.riskexpirydate) as RISKEXPIRYDATE,
               to_varchar(st.riskinceptiondate) as RISKINCEPTIONDATE
          from st1 st
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select POLICY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_HEADER
     where regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_PARTNER_EXTN|OPUS_BJAZ_CTNGY_GC_MEM_DATA|OPUS_BJAZ_CTNGY_PA_MEM_DTLS|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_PA_DETL_EXTN|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS)(, (OPUS_AZBJ_PARTNER_EXTN|OPUS_BJAZ_CTNGY_GC_MEM_DATA|OPUS_BJAZ_CTNGY_PA_MEM_DTLS|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_PA_DETL_EXTN|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS))*$') and POLICY_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.MASTERPOLICYREFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.POLICYREFERENCENUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.POLICYTERM AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.RISKEXPIRYDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.RISKINCEPTIONDATE AS VARCHAR))), ''), '^^')))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'OPUS', 'SAT_POLICY_HEADER', 'stitch_policy_header (10 tables)',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;

-- STEP 3 (pick a key) -- map a sampled BEFORE hkey to its RAW business key. Copy one business_key value to use in STEP 4.
with s_bk as (  -- sampled BEFORE hkeys for this satellite
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_POLICY_HEADER'
)
-- via OPUS_AZBJ_PARTNER_EXTN (BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN)
select 'SAT_POLICY_HEADER' as satellite, 'stitch_policy_header (10 tables)' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("EXISTING_POLICY_PID"::varchar), '')))) AS VARCHAR))), '')) as hkey, (nullif(trim("EXISTING_POLICY_PID"::varchar), '')) as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN
 where (nullif(trim("EXISTING_POLICY_PID"::varchar), '')) is not null and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("EXISTING_POLICY_PID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via OPUS_BJAZ_CTNGY_GC_MEM_DATA (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_GC_MEM_DATA)
select 'SAT_POLICY_HEADER' as satellite, 'stitch_policy_header (10 tables)' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("POLICY_REF"::varchar), '')))) AS VARCHAR))), '')) as hkey, (nullif(trim("POLICY_REF"::varchar), '')) as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_GC_MEM_DATA' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_GC_MEM_DATA
 where (nullif(trim("POLICY_REF"::varchar), '')) is not null and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("POLICY_REF"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via OPUS_BJAZ_CTNGY_PA_MEM_DTLS (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_PA_MEM_DTLS)
select 'SAT_POLICY_HEADER' as satellite, 'stitch_policy_header (10 tables)' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) as hkey, (nullif(trim("CONTRACT_ID"::varchar), '')) as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_PA_MEM_DTLS' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_PA_MEM_DTLS
 where (nullif(trim("CONTRACT_ID"::varchar), '')) is not null and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via OPUS_BJAZ_EC_MEM_DTLS_EXTN (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN)
select 'SAT_POLICY_HEADER' as satellite, 'stitch_policy_header (10 tables)' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) as hkey, (nullif(trim("CONTRACT_ID"::varchar), '')) as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN
 where (nullif(trim("CONTRACT_ID"::varchar), '')) is not null and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via OPUS_BJAZ_HCF_MEMBER_DTLS (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS)
select 'SAT_POLICY_HEADER' as satellite, 'stitch_policy_header (10 tables)' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) as hkey, (nullif(trim("CONTRACT_ID"::varchar), '')) as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS
 where (nullif(trim("CONTRACT_ID"::varchar), '')) is not null and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
