       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) as hkey, (nullif(trim("CONTRACT_ID"::varchar), '')) as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS
 where (nullif(trim("CONTRACT_ID"::varchar), '')) is not null and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s_bk)
