 where (nullif(trim("CONTRACT_ID"::varchar), '')) is not null and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via OPUS_BJAZ_SH_MEM_DTLS_EXTN (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN)
select 'SAT_POLICY_HEADER' as satellite, 'stitch_policy_header (10 tables)' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) as hkey, (nullif(trim("CONTRACT_ID"::varchar), '')) as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN
 where (nullif(trim("CONTRACT_ID"::varchar), '')) is not null and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via OPUS_BJAZ_SPP_MEMBER_DTLS (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS)
select 'SAT_POLICY_HEADER' as satellite, 'stitch_policy_header (10 tables)' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) as hkey, (nullif(trim("CONTRACT_ID"::varchar), '')) as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS
 where (nullif(trim("CONTRACT_ID"::varchar), '')) is not null and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (((nullif(trim("CONTRACT_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s_bk)
limit 20;

-- STEP 4 (force the change) -- fill <BK> from STEP 3, run this UPDATE in UTILS. STEP 5: dbt run --select this sat. STEP 6: set phase='AFTER' and re-run STEP 2.
-- OPUS_AZBJ_PARTNER_EXTN source (BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN): change ONE sampled key
update BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN
   set "POLICY_REF" = coalesce(to_varchar("POLICY_REF"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "EXISTING_POLICY_PID" = '<EXISTING_POLICY_PID>';

-- OPUS_BJAZ_CTNGY_GC_MEM_DATA source (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_GC_MEM_DATA): change ONE sampled key
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_GC_MEM_DATA
   set "MASTER_POLICY_REF" = coalesce(to_varchar("MASTER_POLICY_REF"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "POLICY_REF" = '<POLICY_REF>';

-- OPUS_BJAZ_CTNGY_PA_MEM_DTLS source (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_PA_MEM_DTLS): change ONE sampled key
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_PA_MEM_DTLS
   set "MEMBER_RISK_EXPIRY_DATE" = coalesce(to_varchar("MEMBER_RISK_EXPIRY_DATE"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "CONTRACT_ID" = '<CONTRACT_ID>';

-- OPUS_BJAZ_EC_MEM_DTLS_EXTN source (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN): change ONE sampled key
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN
   set "POLICY_REF" = coalesce(to_varchar("POLICY_REF"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "CONTRACT_ID" = '<CONTRACT_ID>';

-- OPUS_BJAZ_HCF_MEMBER_DTLS source (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS): change ONE sampled key
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS
   set "TO_DATE" = coalesce(to_varchar("TO_DATE"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "CONTRACT_ID" = '<CONTRACT_ID>';

-- OPUS_BJAZ_HC_PART_EXTN source (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HC_PART_EXTN): change ONE sampled key
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HC_PART_EXTN
   set "INCEPTION_DATE" = coalesce(to_varchar("INCEPTION_DATE"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "CONTRACT_ID" = '<CONTRACT_ID>';

-- OPUS_BJAZ_HM_MEMBER_DTLS source (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS): change ONE sampled key
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS
   set "POLICY_REF" = coalesce(to_varchar("POLICY_REF"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "CONTRACT_ID" = '<CONTRACT_ID>';

-- OPUS_BJAZ_PA_DETL_EXTN source (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PA_DETL_EXTN): change ONE sampled key
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PA_DETL_EXTN
   set "INCEPTION_DATE" = coalesce(to_varchar("INCEPTION_DATE"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "CONTRACT_ID" = '<CONTRACT_ID>';

-- OPUS_BJAZ_SH_MEM_DTLS_EXTN source (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN): change ONE sampled key
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN
   set "POLICY_REF" = coalesce(to_varchar("POLICY_REF"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "CONTRACT_ID" = '<CONTRACT_ID>';

-- OPUS_BJAZ_SPP_MEMBER_DTLS source (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS): change ONE sampled key
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS
   set "TO_DATE" = coalesce(to_varchar("TO_DATE"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "CONTRACT_ID" = '<CONTRACT_ID>';

-- STEP 7 (result for THIS sat) -- after AFTER capture, run this. PASS = every changed key got >= 1 new row; NOT TESTED = no change reached the sample.
with b as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_POLICY_HEADER'
),
a as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'AFTER'  and satellite = 'SAT_POLICY_HEADER'
),
k as (
    select b.satellite, b.record_source, b.hkey, b.cdk,
           not equal_null(b.raw_hash, a.raw_hash) as raw_changed,
           a.sat_rows - b.sat_rows as new_rows
      from b join a
        on a.satellite = b.satellite and a.record_source = b.record_source
       and a.hkey = b.hkey and equal_null(a.cdk, b.cdk)
)
select 'OPUS' as project, satellite, record_source,
       count(*) as changed_keys,
       count_if(new_rows >= 1) as changed_with_new_row,
       count_if(new_rows < 1)  as changed_without_new_row,
       iff(changed_keys = 0, 'NOT TESTED (no source change in sample)',
           iff(changed_without_new_row = 0, 'PASS', 'FAIL')) as status
  from k
 where raw_changed
 group by satellite, record_source
 order by iff(status = 'FAIL', 0, 1), record_source;



