-- 13. OPUS — [M2 | automate_dv.ma_sat] SAT_LNK_POLICY_PARTY_ROLE   [Implemented]
-- HASHDIFF column HASHDIFF. Recomputed exactly as automate_dv 0.11.5 / sat_multi_source
-- computes it, from the payload stored on the same row. A match proves every payload
-- change changes the HASHDIFF, which is what drives a new row. standard satellite,
-- automate_dv.ma_sat; PK POLICY_PARTY_HKEY, child key ROLE_SEQUENCE; 1 RECORD_SOURCE
-- group(s): OPUS_OCP_INTERESTED_PARTIES [1 col(s)]. Multi-active: compared per (key,
-- child key); latest = max LOAD_DATETIME per member.
----------------------------------------------------------------------------------------
-- STEP 1 (static, run anytime) -- HASHDIFF integrity. PASS here = the change-detection fingerprint is sound. SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'OPUS' as project, 'SAT_LNK_POLICY_PARTY_ROLE' as satellite, 'OPUS_OCP_INTERESTED_PARTIES' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF is null) as null_hashdiff,
       count_if(HASHDIFF <> CAST(MD5_BINARY(IFNULL(NULLIF(UPPER(TRIM(CAST(ROLE_SEQUENCE AS VARCHAR))), ''), '^^')) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF <> CAST(MD5_BINARY(IFNULL(NULLIF(UPPER(TRIM(CAST(ROLE_SEQUENCE AS VARCHAR))), ''), '^^')) AS BINARY(16)), to_varchar(POLICY_PARTY_HKEY, 'HEX'), null)) within group (order by POLICY_PARTY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_LNK_POLICY_PARTY_ROLE
 where (RECORD_SOURCE = 'OPUS_OCP_INTERESTED_PARTIES');

-- STEP 2 (BEFORE) -- set $DM_H_RUN (with your <M#>) and $DM_H_PHASE='BEFORE', then run this CDC capture. Re-run it again in STEP 6 after setting phase to AFTER.
insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct POLICY_PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_LNK_POLICY_PARTY_ROLE where RECORD_SOURCE = 'OPUS_OCP_INTERESTED_PARTIES' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_LNK_POLICY_PARTY_ROLE' and record_source = 'OPUS_OCP_INTERESTED_PARTIES'
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_partner__ocp_interested_parties
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_POLICY_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), '')) || '|' || (nullif(trim("CONTRACT_ID"::varchar), '')) AS VARCHAR))), '')) as hkey,
               to_varchar(("IP_NO"::number)) as cdk_1,
               ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
               to_varchar(("IP_NO"::number)) as ROLE_SEQUENCE
          from BAGIC_PREPROD_CURATED_DB.UTILS.OCP_INTERESTED_PARTIES
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey, cdk_1 order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key  (key-only: rows PER PARENT KEY)
    select POLICY_PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_LNK_POLICY_PARTY_ROLE
     where RECORD_SOURCE = 'OPUS_OCP_INTERESTED_PARTIES' and POLICY_PARTY_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- key-only: hash of the whole member set per parent key
    select e.hkey, '' as cdk,
           md5(listagg(distinct coalesce(to_varchar(e.cdk_1), '^^'), ',') within group (order by coalesce(to_varchar(e.cdk_1), '^^'))) as raw_hash
      from e1 e group by 1
)
select $DM_H_RUN, $DM_H_PHASE, 'OPUS', 'SAT_LNK_POLICY_PARTY_ROLE', 'OPUS_OCP_INTERESTED_PARTIES',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;

-- STEP 3 (pick a key) -- map a sampled BEFORE hkey to its RAW business key. Copy one business_key value to use in STEP 4.
with s_bk as (  -- sampled BEFORE hkeys for this satellite
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_LNK_POLICY_PARTY_ROLE'
)
-- via stg_partner__ocp_interested_parties (BAGIC_PREPROD_CURATED_DB.UTILS.OCP_INTERESTED_PARTIES)
select 'SAT_LNK_POLICY_PARTY_ROLE' as satellite, 'OPUS_OCP_INTERESTED_PARTIES' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_POLICY_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), '')) || '|' || (nullif(trim("CONTRACT_ID"::varchar), '')) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("PARTNER_ID"), '^^') || '|' || coalesce(to_varchar("CONTRACT_ID"), '^^') as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.OCP_INTERESTED_PARTIES' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.OCP_INTERESTED_PARTIES
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_POLICY_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), '')) || '|' || (nullif(trim("CONTRACT_ID"::varchar), '')) AS VARCHAR))), '')) in (select hkey from s_bk)
limit 20;

-- STEP 4 (force the change) -- fill <BK> from STEP 3, run this UPDATE in UTILS. STEP 5: dbt run --select this sat. STEP 6: set phase='AFTER' and re-run STEP 2.
-- OPUS_OCP_INTERESTED_PARTIES (BAGIC_PREPROD_CURATED_DB.UTILS.OCP_INTERESTED_PARTIES): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PREPROD_CURATED_DB.UTILS.OCP_INTERESTED_PARTIES
   set "IP_NO" = 999999,
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "PARTNER_ID" = '<PARTNER_ID>' and "CONTRACT_ID" = '<CONTRACT_ID>';

-- STEP 7 (result for THIS sat) -- after AFTER capture, run this. PASS = every changed key got >= 1 new row; NOT TESTED = no change reached the sample. NOTE: this is a KEY-ONLY multi-active sat (payload = child key), so a change creates a NEW member; counting is PER PARENT KEY -- PASS = the parent key gained a row.
with b as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_LNK_POLICY_PARTY_ROLE'
),
a as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'AFTER'  and satellite = 'SAT_LNK_POLICY_PARTY_ROLE'
),
k as (
    select b.satellite, b.record_source, b.hkey, b.cdk,
           not equal_null(b.raw_hash, a.raw_hash) as raw_changed,
           a.sat_rows - b.sat_rows as new_rows
      from b join a
        on a.satellite = b.satellite and a.record_source = b.record_source
       and a.hkey = b.hkey and equal_null(a.cdk, b.cdk)
)
select 'OPUS' as project, satellite, record_source,
       count(*) as changed_keys,
       count_if(new_rows >= 1) as changed_with_new_row,
       count_if(new_rows < 1)  as changed_without_new_row,
       iff(changed_keys = 0, 'NOT TESTED (no source change in sample)',
           iff(changed_without_new_row = 0, 'PASS', 'FAIL')) as status
  from k
 where raw_changed
 group by satellite, record_source
 order by iff(status = 'FAIL', 0, 1), record_source;



