x5 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, coalesce(e.cdk_1, '^^') as cdk, min(md5(IFNULL(NULLIF(UPPER(TRIM(CAST(e.INCEPTION_DATE AS VARCHAR))), ''), '^^'))) as raw_hash
