  from n5 n full outer join x5 x on x.hkey = n.hkey and x.cdk = n.cdk;

-- STEP 3 (pick a key) -- map a sampled BEFORE hkey to its RAW business key. Copy one business_key value to use in STEP 4.
with s_bk as (  -- sampled BEFORE hkeys for this satellite
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_AUG_POLICY'
)
-- via stg_partner__bjaz_hlt_ensure_mem_dtls (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HLT_ENSURE_MEM_DTLS)
select 'SAT_AUG_POLICY' as satellite, 'OPUS_BJAZ_HLT_ENSURE_MEM_DTLS' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || ((nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("CONTRACT_ID"), '^^') as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HLT_ENSURE_MEM_DTLS' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HLT_ENSURE_MEM_DTLS
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || ((nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via stg_partner__bjaz_hm_member_dtls (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS)
select 'SAT_AUG_POLICY' as satellite, 'OPUS_BJAZ_HM_MEMBER_DTLS' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || ((nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("CONTRACT_ID"), '^^') as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || ((nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via stg_partner__bjaz_pa_detl_extn (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PA_DETL_EXTN)
select 'SAT_AUG_POLICY' as satellite, 'OPUS_BJAZ_PA_DETL_EXTN' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || ((nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("CONTRACT_ID"), '^^') as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PA_DETL_EXTN' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PA_DETL_EXTN
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || ((nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via stg_partner__bjaz_ec_mem_dtls_extn (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN)
select 'SAT_AUG_POLICY' as satellite, 'OPUS_BJAZ_EC_MEM_DTLS_EXTN' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || ((nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("CONTRACT_ID"), '^^') as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || ((nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via stg_partner__bjaz_sh_mem_dtls_extn (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN)
select 'SAT_AUG_POLICY' as satellite, 'OPUS_BJAZ_SH_MEM_DTLS_EXTN' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || ((nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("CONTRACT_ID"), '^^') as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || ((nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from s_bk)
limit 20;

-- STEP 4 (force the change) -- fill <BK> from STEP 3, run this UPDATE in UTILS. STEP 5: dbt run --select this sat. STEP 6: set phase='AFTER' and re-run STEP 2.
-- OPUS_BJAZ_HLT_ENSURE_MEM_DTLS (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HLT_ENSURE_MEM_DTLS): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HLT_ENSURE_MEM_DTLS
   set "PREVIOUS_CUM_AMOUNT" = coalesce(to_varchar("PREVIOUS_CUM_AMOUNT"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "CONTRACT_ID" = '<CONTRACT_ID>';

-- OPUS_BJAZ_HM_MEMBER_DTLS (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS
   set "CUMM_BONUS" = coalesce(to_varchar("CUMM_BONUS"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "CONTRACT_ID" = '<CONTRACT_ID>';

-- OPUS_BJAZ_PA_DETL_EXTN (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PA_DETL_EXTN): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PA_DETL_EXTN
   set "CUMMULATIVE_AMT" = coalesce(to_varchar("CUMMULATIVE_AMT"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "CONTRACT_ID" = '<CONTRACT_ID>';

-- OPUS_BJAZ_EC_MEM_DTLS_EXTN (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN
   set "INCEPTION_DATE" = coalesce(to_varchar("INCEPTION_DATE"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "CONTRACT_ID" = '<CONTRACT_ID>';

-- OPUS_BJAZ_SH_MEM_DTLS_EXTN (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN
   set "INCEPTION_DATE" = coalesce(to_varchar("INCEPTION_DATE"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "CONTRACT_ID" = '<CONTRACT_ID>';

-- STEP 7 (result for THIS sat) -- after AFTER capture, run this. PASS = every changed key got >= 1 new row; NOT TESTED = no change reached the sample.
with b as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_AUG_POLICY'
),
a as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'AFTER'  and satellite = 'SAT_AUG_POLICY'
),
k as (
    select b.satellite, b.record_source, b.hkey, b.cdk,
           not equal_null(b.raw_hash, a.raw_hash) as raw_changed,
           a.sat_rows - b.sat_rows as new_rows
      from b join a
        on a.satellite = b.satellite and a.record_source = b.record_source
       and a.hkey = b.hkey and equal_null(a.cdk, b.cdk)
)
select 'OPUS' as project, satellite, record_source,
       count(*) as changed_keys,
       count_if(new_rows >= 1) as changed_with_new_row,
       count_if(new_rows < 1)  as changed_without_new_row,
       iff(changed_keys = 0, 'NOT TESTED (no source change in sample)',
           iff(changed_without_new_row = 0, 'PASS', 'FAIL')) as status
  from k
 where raw_changed
 group by satellite, record_source
 order by iff(status = 'FAIL', 0, 1), record_source;



----------------------------------------------------------------------------------------
-- 15. OPUS — [M2 | ma_sat_multi_source] SAT_PARTY_CONTACT_ADDRESS_LINK   [Implemented]
-- HASHDIFF column HASHDIFF. Recomputed exactly as automate_dv 0.11.5 / sat_multi_source
-- computes it, from the payload stored on the same row. A match proves every payload
-- change changes the HASHDIFF, which is what drives a new row. standard satellite,
-- ma_sat_multi_source; PK PARTY_LOCATION_HKEY, child key ADDRESS_USAGE_TYPE; 2
-- RECORD_SOURCE group(s): OPUS_BJAZ_CP_ADDRESS_LINK [1 col(s)],
-- OPUS_BJAZ_T_CKYC_PERSONAL_DTLS [0 col(s)]. Multi-active: compared per (key, child
-- key); latest = max LOAD_DATETIME per member.
----------------------------------------------------------------------------------------
-- STEP 1 (static, run anytime) -- HASHDIFF integrity. PASS here = the change-detection fingerprint is sound. SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'OPUS' as project, 'SAT_PARTY_CONTACT_ADDRESS_LINK' as satellite, '2 RECORD_SOURCEs sharing one HASHDIFF column list' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF is null) as null_hashdiff,
       count_if(HASHDIFF <> CAST(MD5_BINARY(IFNULL(NULLIF(UPPER(TRIM(CAST(PRIMARY_ADDRESS_INDICATOR AS VARCHAR))), ''), '^^')) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF <> CAST(MD5_BINARY(IFNULL(NULLIF(UPPER(TRIM(CAST(PRIMARY_ADDRESS_INDICATOR AS VARCHAR))), ''), '^^')) AS BINARY(16)), to_varchar(PARTY_LOCATION_HKEY, 'HEX'), null)) within group (order by PARTY_LOCATION_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_CONTACT_ADDRESS_LINK
 where (RECORD_SOURCE = 'OPUS_BJAZ_CP_ADDRESS_LINK') or (RECORD_SOURCE = 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS');

-- STEP 2 (BEFORE) -- set $DM_H_RUN (with your <M#>) and $DM_H_PHASE='BEFORE', then run this CDC capture. Re-run it again in STEP 6 after setting phase to AFTER.
insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_LOCATION_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_CONTACT_ADDRESS_LINK where RECORD_SOURCE = 'OPUS_BJAZ_CP_ADDRESS_LINK' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_PARTY_CONTACT_ADDRESS_LINK' and record_source = 'OPUS_BJAZ_CP_ADDRESS_LINK'
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_partner__bjaz_cp_address_link
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_PARTY_LOCATION|' || (nullif(trim("PART_ID"::varchar), '')) || '|' || (nullif(trim("ADD_ID"::varchar), '')) AS VARCHAR))), '')) as hkey,
               to_varchar(to_varchar(("ADD_TYPE"::number))) as cdk_1,
               ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
               to_varchar((nullif(trim("PRIMARY_YN"::varchar), ''))) as PRIMARY_ADDRESS_INDICATOR
          from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CP_ADDRESS_LINK
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey, cdk_1 order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select PARTY_LOCATION_HKEY as hkey, coalesce(to_varchar(ADDRESS_USAGE_TYPE), '^^') as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_CONTACT_ADDRESS_LINK
     where RECORD_SOURCE = 'OPUS_BJAZ_CP_ADDRESS_LINK' and PARTY_LOCATION_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, coalesce(e.cdk_1, '^^') as cdk, min(md5(IFNULL(NULLIF(UPPER(TRIM(CAST(e.PRIMARY_ADDRESS_INDICATOR AS VARCHAR))), ''), '^^'))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'OPUS', 'SAT_PARTY_CONTACT_ADDRESS_LINK', 'OPUS_BJAZ_CP_ADDRESS_LINK',
