x2 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(IFNULL(NULLIF(UPPER(TRIM(CAST(e.VERIFICATION_RESPONSE_MESSAGE AS VARCHAR))), ''), '^^'))) as raw_hash
