  from n4 n full outer join x4 x on x.hkey = n.hkey and x.cdk = n.cdk;

-- STEP 3 (pick a key) -- map a sampled BEFORE hkey to its RAW business key. Copy one business_key value to use in STEP 4.
with s_bk as (  -- sampled BEFORE hkeys for this satellite
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_PARTY_BANKING'
)
-- via stg_partner__azbj_partner_extn (BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN)
select 'SAT_PARTY_BANKING' as satellite, 'OPUS_AZBJ_PARTNER_EXTN' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("PART_ID"), '^^') as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via stg_partner__bjaz_clm_supp_extn (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN)
select 'SAT_PARTY_BANKING' as satellite, 'OPUS_BJAZ_CLM_SUPP_EXTN' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("PARTNER_ID"), '^^') as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via stg_partner__bjaz_ctngy_pa_mem_dtls (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_PA_MEM_DTLS)
select 'SAT_PARTY_BANKING' as satellite, 'OPUS_BJAZ_CTNGY_PA_MEM_DTLS' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("PARTNER_ID"), '^^') as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_PA_MEM_DTLS' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_PA_MEM_DTLS
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via stg_partner__bjaz_hm_member_dtls (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS)
select 'SAT_PARTY_BANKING' as satellite, 'OPUS_BJAZ_HM_MEMBER_DTLS' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("PARTNER_ID"), '^^') as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from s_bk)
limit 20;

-- STEP 4 (force the change) -- fill <BK> from STEP 3, run this UPDATE in UTILS. STEP 5: dbt run --select this sat. STEP 6: set phase='AFTER' and re-run STEP 2.
-- OPUS_AZBJ_PARTNER_EXTN (BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN
   set "ACCOUNT_NO" = coalesce(to_varchar("ACCOUNT_NO"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "PART_ID" = '<PART_ID>';

-- OPUS_BJAZ_CLM_SUPP_EXTN (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN
   set "SUPP_BANK_ACC_NO" = coalesce(to_varchar("SUPP_BANK_ACC_NO"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "PARTNER_ID" = '<PARTNER_ID>';

-- OPUS_BJAZ_CTNGY_PA_MEM_DTLS (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_PA_MEM_DTLS): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_PA_MEM_DTLS
   set "LOAN_ACCOUNT_NO" = coalesce(to_varchar("LOAN_ACCOUNT_NO"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "PARTNER_ID" = '<PARTNER_ID>';

-- OPUS_BJAZ_HM_MEMBER_DTLS (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS
   set "BANK_AC_NO" = coalesce(to_varchar("BANK_AC_NO"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "PARTNER_ID" = '<PARTNER_ID>';

-- STEP 7 (result for THIS sat) -- after AFTER capture, run this. PASS = every changed key got >= 1 new row; NOT TESTED = no change reached the sample.
with b as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_PARTY_BANKING'
),
a as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'AFTER'  and satellite = 'SAT_PARTY_BANKING'
),
k as (
    select b.satellite, b.record_source, b.hkey, b.cdk,
           not equal_null(b.raw_hash, a.raw_hash) as raw_changed,
           a.sat_rows - b.sat_rows as new_rows
      from b join a
        on a.satellite = b.satellite and a.record_source = b.record_source
       and a.hkey = b.hkey and equal_null(a.cdk, b.cdk)
)
select 'OPUS' as project, satellite, record_source,
       count(*) as changed_keys,
       count_if(new_rows >= 1) as changed_with_new_row,
       count_if(new_rows < 1)  as changed_without_new_row,
       iff(changed_keys = 0, 'NOT TESTED (no source change in sample)',
           iff(changed_without_new_row = 0, 'PASS', 'FAIL')) as status
  from k
 where raw_changed
 group by satellite, record_source
 order by iff(status = 'FAIL', 0, 1), record_source;



----------------------------------------------------------------------------------------
-- 18. OPUS — [M2 | sat_multi_source] SAT_PARTY_KYC   [Implemented]
-- HASHDIFF column HASHDIFF. Recomputed exactly as automate_dv 0.11.5 / sat_multi_source
-- computes it, from the payload stored on the same row. A match proves every payload
-- change changes the HASHDIFF, which is what drives a new row. standard satellite,
-- sat_multi_source; PK PARTY_HKEY; 5 RECORD_SOURCE group(s):
-- OPUS_BJAZ_T_CKYC_PERSONAL_DTLS [2 col(s)], OPUS_BJAZ_T_CKYC_REL_PERSION_DTLS [1
-- col(s)], OPUS_BJAZ_T_CKYC_SEARCH [4 col(s)], OPUS_BJAZ_T_KYC_DETAILS [2 col(s)],
-- OPUS_BJAZ_T_KYC_INCOMING [2 col(s)].
----------------------------------------------------------------------------------------
-- STEP 1 (static, run anytime) -- HASHDIFF integrity. PASS here = the change-detection fingerprint is sound. SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'OPUS' as project, 'SAT_PARTY_KYC' as satellite, '5 RECORD_SOURCEs sharing one HASHDIFF column list' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF is null) as null_hashdiff,
       count_if(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(CKYCNUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CKYCREGISTRATIONSTATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(KYCCOMPLETIONDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(KYCMODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(KYCSTATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(KYCTYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(LASTKYCREVIEWDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OVDSUBMITTEDCOUNT AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(CKYCNUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CKYCREGISTRATIONSTATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(KYCCOMPLETIONDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(KYCMODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(KYCSTATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(KYCTYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(LASTKYCREVIEWDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OVDSUBMITTEDCOUNT AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_KYC
 where (RECORD_SOURCE = 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS') or (RECORD_SOURCE = 'OPUS_BJAZ_T_CKYC_REL_PERSION_DTLS') or (RECORD_SOURCE = 'OPUS_BJAZ_T_CKYC_SEARCH') or (RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_DETAILS') or (RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_INCOMING');

-- STEP 2 (BEFORE) -- set $DM_H_RUN (with your <M#>) and $DM_H_PHASE='BEFORE', then run this CDC capture. Re-run it again in STEP 6 after setting phase to AFTER.
insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_KYC where RECORD_SOURCE = 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_PARTY_KYC' and record_source = 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS'
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_partner__bjaz_t_ckyc_personal_dtls
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif('CKYC:' || upper(trim(coalesce((nullif(trim("CKYC_NO"::varchar), '')),''))), 'CKYC:')) AS VARCHAR))), '')) as hkey,
               (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as ldts,
               to_varchar((nullif(trim("ACC_TYPE"::varchar), ''))) as KYCTYPE,
               to_varchar((nullif(trim("NUM_IDENTITY"::varchar), ''))) as OVDSUBMITTEDCOUNT
          from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_PERSONAL_DTLS
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_KYC
     where RECORD_SOURCE = 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS' and PARTY_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.KYCTYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.OVDSUBMITTEDCOUNT AS VARCHAR))), ''), '^^')))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'OPUS', 'SAT_PARTY_KYC', 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s2 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
