  from n5 n full outer join x5 x on x.hkey = n.hkey and x.cdk = n.cdk;

-- STEP 3 (pick a key) -- map a sampled BEFORE hkey to its RAW business key. Copy one business_key value to use in STEP 4.
with s_bk as (  -- sampled BEFORE hkeys for this satellite
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_PARTY_KYC'
)
-- via stg_partner__bjaz_t_ckyc_personal_dtls (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_PERSONAL_DTLS)
select 'SAT_PARTY_KYC' as satellite, 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif('CKYC:' || upper(trim(coalesce((nullif(trim("CKYC_NO"::varchar), '')),''))), 'CKYC:')) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("CKYC_NO"), '^^') as business_key, (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_PERSONAL_DTLS' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_PERSONAL_DTLS
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif('CKYC:' || upper(trim(coalesce((nullif(trim("CKYC_NO"::varchar), '')),''))), 'CKYC:')) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via stg_partner__bjaz_t_ckyc_rel_persion_dtls (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_REL_PERSION_DTLS)
select 'SAT_PARTY_KYC' as satellite, 'OPUS_BJAZ_T_CKYC_REL_PERSION_DTLS' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif('CKYC:' || upper(trim(coalesce((nullif(trim("CKYC_NO"::varchar), '')),''))), 'CKYC:')) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("CKYC_NO"), '^^') as business_key, (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_REL_PERSION_DTLS' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_REL_PERSION_DTLS
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif('CKYC:' || upper(trim(coalesce((nullif(trim("CKYC_NO"::varchar), '')),''))), 'CKYC:')) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via stg_partner__bjaz_t_ckyc_search (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_SEARCH)
select 'SAT_PARTY_KYC' as satellite, 'OPUS_BJAZ_T_CKYC_SEARCH' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(upper(trim(coalesce((nullif(trim("CATEGORY"::varchar), '')),''))) || ':' || upper(trim(coalesce((nullif(trim("INPUT"::varchar), '')),''))), ':')) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("CATEGORY"), '^^') || '|' || coalesce(to_varchar("INPUT"), '^^') as business_key, (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_SEARCH' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_SEARCH
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(upper(trim(coalesce((nullif(trim("CATEGORY"::varchar), '')),''))) || ':' || upper(trim(coalesce((nullif(trim("INPUT"::varchar), '')),''))), ':')) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via stg_partner__bjaz_t_kyc_details (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_DETAILS)
select 'SAT_PARTY_KYC' as satellite, 'OPUS_BJAZ_T_KYC_DETAILS' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(upper(trim(coalesce((nullif(trim("CATEGORY"::varchar), '')),''))) || ':' || upper(trim(coalesce((nullif(trim("INPUT"::varchar), '')),''))), ':')) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("CATEGORY"), '^^') || '|' || coalesce(to_varchar("INPUT"), '^^') as business_key, (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_DETAILS' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_DETAILS
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(upper(trim(coalesce((nullif(trim("CATEGORY"::varchar), '')),''))) || ':' || upper(trim(coalesce((nullif(trim("INPUT"::varchar), '')),''))), ':')) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via stg_partner__bjaz_t_kyc_incoming (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_INCOMING)
select 'SAT_PARTY_KYC' as satellite, 'OPUS_BJAZ_T_KYC_INCOMING' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(upper(trim(coalesce((nullif(trim("SEARCH_CATEGORY"::varchar), '')),''))) || ':' || upper(trim(coalesce((nullif(trim("SEARCH_INPUT"::varchar), '')),''))), ':')) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("SEARCH_CATEGORY"), '^^') || '|' || coalesce(to_varchar("SEARCH_INPUT"), '^^') as business_key, (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_INCOMING' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_INCOMING
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(upper(trim(coalesce((nullif(trim("SEARCH_CATEGORY"::varchar), '')),''))) || ':' || upper(trim(coalesce((nullif(trim("SEARCH_INPUT"::varchar), '')),''))), ':')) AS VARCHAR))), '')) in (select hkey from s_bk)
limit 20;

-- STEP 4 (force the change) -- fill <BK> from STEP 3, run this UPDATE in UTILS. STEP 5: dbt run --select this sat. STEP 6: set phase='AFTER' and re-run STEP 2.
-- OPUS_BJAZ_T_CKYC_PERSONAL_DTLS (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_PERSONAL_DTLS): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_PERSONAL_DTLS
