-- OPUS_BJAZ_T_CKYC_REL_PERSION_DTLS (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_REL_PERSION_DTLS): change ONE sampled key (fill <..> from the b-map result)
