-- OPUS_BJAZ_T_CKYC_SEARCH (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_SEARCH): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_SEARCH
