       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (case when upper(trim((nullif(trim("FIELD_TYPE"::varchar), '')))) like 'POLICY%' then trim((nullif(trim("FIELD_VALUE"::varchar), ''))) end) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("FIELD_TYPE"), '^^') || '|' || coalesce(to_varchar("FIELD_VALUE"), '^^') as business_key, (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as inc_job_updated_at,
