  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_INCOMING
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (case when upper(trim((nullif(trim("FIELD_TYPE"::varchar), '')))) like 'POLICY%' then trim((nullif(trim("FIELD_VALUE"::varchar), ''))) end) AS VARCHAR))), '')) in (select hkey from s_bk)
