       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_POA_DOCUMENT' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_POA_DOCUMENT
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (upper(case when upper(trim((nullif(trim("FIELD_TYPE"::varchar), '')))) like 'POLICY%' then trim((nullif(trim("FIELD_VALUE"::varchar), ''))) end)) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via stg_partner__bjaz_t_kyc_poi_document (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_POI_DOCUMENT)
select 'SAT_POLICY_CLASSIFICATION' as satellite, 'OPUS_BJAZ_T_KYC_POI_DOCUMENT' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (upper(case when upper(trim((nullif(trim("FIELD_TYPE"::varchar), '')))) like 'POLICY%' then trim((nullif(trim("FIELD_VALUE"::varchar), ''))) end)) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("FIELD_TYPE"), '^^') || '|' || coalesce(to_varchar("FIELD_VALUE"), '^^') as business_key, (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_POI_DOCUMENT' as raw_table
