limit 20;

-- STEP 4 (force the change) -- fill <BK> from STEP 3, run this UPDATE in UTILS. STEP 5: dbt run --select this sat. STEP 6: set phase='AFTER' and re-run STEP 2.
-- OPUS_BJAZ_T_KYC_DETAILS (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_DETAILS): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_DETAILS
   set "BUSINESS_TYPE" = coalesce(to_varchar("BUSINESS_TYPE"), '') || '_T',
       "INC_JOB_UPDATED_AT" = current_timestamp()
 where "FIELD_TYPE" = '<FIELD_TYPE>' and "FIELD_VALUE" = '<FIELD_VALUE>';

-- OPUS_BJAZ_T_KYC_INCOMING (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_INCOMING): change ONE sampled key (fill <..> from the b-map result)
