-- OPUS_BJAZ_T_KYC_POA_DOCUMENT (BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_POA_DOCUMENT): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_POA_DOCUMENT
