select 'SAT_AUG_LOCATION' as satellite, 'OPUS_CP_ADDRESSES' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || ((nullif(trim("ADD_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("ADD_ID"), '^^') as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.CP_ADDRESSES' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.CP_ADDRESSES
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || ((nullif(trim("ADD_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via stg_partner__cp_partners (BAGIC_PREPROD_CURATED_DB.UTILS.CP_PARTNERS)
select 'SAT_AUG_LOCATION' as satellite, 'OPUS_CP_PARTNERS' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || ((nullif(trim("ADD_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("ADD_ID"), '^^') as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.CP_PARTNERS' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.CP_PARTNERS
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || ((nullif(trim("ADD_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from s_bk)
limit 20;

