       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("PART_ID"), '^^') as business_key, ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at,
       'BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN' as raw_table
  from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from s_bk)
