       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(upper(trim(coalesce((nullif(trim("CATEGORY"::varchar), '')),''))) || ':' || upper(trim(coalesce((nullif(trim("INPUT"::varchar), '')),''))), ':')) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("CATEGORY"), '^^') || '|' || coalesce(to_varchar("INPUT"), '^^') as business_key, (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as inc_job_updated_at,
