 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(upper(trim(coalesce((nullif(trim("CATEGORY"::varchar), '')),''))) || ':' || upper(trim(coalesce((nullif(trim("INPUT"::varchar), '')),''))), ':')) AS VARCHAR))), '')) in (select hkey from s_bk)
limit 20;

-- STEP 4 (force the change) -- fill <BK> from STEP 3, run this UPDATE in UTILS. STEP 5: dbt run --select this sat. STEP 6: set phase='AFTER' and re-run STEP 2.
